using Astrea.BattleActions;

namespace Astrea;

public class GainSandsOfTimeBasedWhereXCustomDescription : CustomBattleActionDescription
{
	protected string GetGainSandsOfTimeDescription(BattleAction battleAction)
	{
		return (battleAction as GainSandsOfTimeBasedAction).GainSandsOfTimeEffectAction.GetActionDescription(-1).RemoveLast();
	}

	protected string GetFormattedDescription(BattleAction battleAction, string secondArgument)
	{
		return base.localizationManager.GetLocalizedWhereX(GetGainSandsOfTimeDescription(battleAction), y: false, secondArgument);
	}
}
